import json
with open('/app/resources/treasury_bulletin_1953_03.json') as f:
    d = json.load(f)

# Look for market quotations (Section I) specifically
# This should have the 'Amount out-standing' column

def find_tables_with_keyword(obj, keyword, path=''):
    if isinstance(obj, str):
        if keyword.lower() in obj.lower():
            print(f'{path}: {obj[:500]}...')
    elif isinstance(obj, dict):
        for k, v in obj.items():
            find_tables_with_keyword(v, keyword, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            find_tables_with_keyword(v, keyword, f'{path}[{i}]')

# Find tables with 'Amount out-standing'
find_tables_with_keyword(d, 'Amount out-standing')
